-- R8 readiness — PRODUCTION MIGRATION (PREPARED ONLY; NOT RUN BY ANY AGENT OR CI).
-- Source: database/inventory_atomic.sql on branch qa/r8-readiness-20261109 (generated by qa/build-r8-migration.mjs).
-- Requires separate, explicit owner approval before execution. It changes FUNCTIONS and adds two private tables
-- (inventory_private.material_code_registry, backfilled with existing codes, and inventory_private.category_policy,
-- seeded with the five approved prefixes/ranges). It does NOT update any material, transaction, setting, user or
-- audit row, and does NOT archive or reconcile PES-1001 (PES-1001 stays reported as drift and ordinary changes to it
-- are refused with INVENTORY_RECONCILE_REQUIRED until the separately approved reconcile runs).
--
-- Execution mode: psql -v ON_ERROR_STOP=1 --single-transaction is NOT needed (the file has its own BEGIN/COMMIT);
-- run it in ONE plain session (psql -v ON_ERROR_STOP=1 -f R8_PRODUCTION_MIGRATION.sql), never inside a wrapper
-- that opens its own transaction, and never statement-by-statement in a pooler that may switch sessions.
--
-- Deploy order (see docs/R8_RELEASE_AND_ROLLBACK_AR.md):
--   1. Announce a short no-entry window; every device shows 0 pending / 0 blocked in the sync panel (do NOT erase queues).
--   2. Take and verify the full backup (docs/R8_BACKUP_RESTORE_DRILL_AR.md). Record md5(prosrc) of commit_inventory/validate_inventory.
--   3. Run THIS file once, as one transaction. It stops (and changes nothing) on any baseline drift or policy mismatch.
--   4. Run the read-only check: SELECT public.inventory_projection_drift(); — expect PES-1001 reported as drift (stored 12, ledger 10).
--   5. Deploy the matching client build only after the PR is reviewed/merged by the owner. Old clients remain compatible
--      (server ignores client-supplied derived/lifecycle fields).
--   6. PES-1001 reconcile/archive are SEPARATE approved changes (mode 'reconcile' then mode 'lifecycle'), never part of this file.
BEGIN;
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(824671520); -- same writer lock as commit_inventory: holds writes for the duration
DO $r8_pre$
DECLARE c text:=(SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='inventory_private' AND p.proname='commit_inventory'); v text:=(SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='inventory_private' AND p.proname='validate_inventory'); rp text:=(SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='inventory_private' AND p.proname='restore_preview'); sh text:=(SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='inventory_private' AND p.proname='state_hash'); cats jsonb; names jsonb; reused jsonb;
BEGIN
 IF c IS DISTINCT FROM 'c10026ce626d134deda991fe78e63057' OR v IS DISTINCT FROM 'e3fdfa9cff80c8b710d6e09d80bfeeab'
    OR rp IS DISTINCT FROM 'd7c4e0bc52a0b17912326345f0280bb2' OR sh IS DISTINCT FROM 'e743ed68bd86b4619ae3164ef10808ce' THEN
   RAISE EXCEPTION 'R8_MIGRATION_BASELINE_DRIFT commit=% validate=% restore_preview=% state_hash=% (expected main 6933d16). Stop and re-review.',c,v,rp,sh;
 END IF;
 -- A pre-existing registry is accepted only with the exact R8 shape (roll-forward after an R8 rollback) and only when
 -- no code it reserves was taken by a DIFFERENT material while rolled back (RT-R8-08): such a conflict is listed and stops.
 IF to_regclass('inventory_private.material_code_registry') IS NOT NULL THEN
   IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='inventory_private' AND table_name='material_code_registry'
        AND column_name IN ('code_key','code','prefix','number','material_id','source','reserved_at'))<>7 THEN
     RAISE EXCEPTION 'R8_MIGRATION_REGISTRY_SHAPE_UNEXPECTED';
   END IF;
   EXECUTE $q$SELECT jsonb_agg(jsonb_build_array(r.code,r.material_id,m.id)) FROM inventory_private.material_code_registry r
     JOIN public.materials m ON lower(btrim(m.data->>'code'))=r.code_key AND m.id<>r.material_id$q$ INTO reused;
   IF reused IS NOT NULL THEN RAISE EXCEPTION 'R8_MIGRATION_CODE_REUSED_DURING_ROLLBACK %',reused; END IF;
 END IF;
 IF to_regclass('inventory_private.category_policy') IS NOT NULL THEN
   EXECUTE $q$SELECT jsonb_agg(jsonb_build_array(prefix,start_range,end_range) ORDER BY prefix) FROM inventory_private.category_policy$q$ INTO cats;
   IF cats IS DISTINCT FROM '[["CHM",5001,5999],["EQP",3001,3999],["PES",1001,1999],["ROD",4001,4999],["SAN",2001,2999]]'::jsonb THEN
     RAISE EXCEPTION 'R8_MIGRATION_POLICY_TABLE_UNEXPECTED %',cats;
   END IF;
 END IF;
 SELECT jsonb_agg(x->>'name' ORDER BY x->>'prefix') INTO names FROM public.settings s, jsonb_array_elements(s.data->'categories') x WHERE s.id='app_config';
 IF names IS DISTINCT FROM '["كلور ومواد كيميائية","معدات رش ومكافحة","مبيدات حشرية","طعوم قوارض","معقمات ومطهرات"]'::jsonb THEN
   RAISE EXCEPTION 'R8_MIGRATION_CATEGORY_NAMES_MISMATCH %',names;
 END IF;
 -- R8-POL-01/02 owner decisions: exactly the five live groups, prefixes and ranges.
 SELECT jsonb_agg(jsonb_build_array(x->>'prefix',(x->>'startRange')::numeric,(x->>'endRange')::numeric) ORDER BY x->>'prefix') INTO cats
   FROM public.settings s, jsonb_array_elements(s.data->'categories') x WHERE s.id='app_config';
 IF cats IS DISTINCT FROM '[["CHM",5001,5999],["EQP",3001,3999],["PES",1001,1999],["ROD",4001,4999],["SAN",2001,2999]]'::jsonb THEN
   RAISE EXCEPTION 'R8_MIGRATION_POLICY_MISMATCH %',cats;
 END IF;
END $r8_pre$;

-- Atomic inventory API. No new business/queue table; immutable audit rows are receipts.
-- The private definer is intentional: direct JSON document writes are revoked.
-- Every entry checks the current Auth UID and live profile permissions; never JWT user_metadata.
-- R8 (QA-20261109): server-owned material projections (R8-DATA-01), reversible logical archive
-- lifecycle (R8-ARC-01), category/code policy enforcement with a permanent private code registry
-- (R8-CODE-01 / R8-POL-01/02), read-only drift check and audited reconcile mode.
CREATE UNIQUE INDEX IF NOT EXISTS inventory_material_code_unique ON public.materials (lower(btrim(data->>'code')));
CREATE UNIQUE INDEX IF NOT EXISTS inventory_transaction_number_unique ON public.transactions (lower(btrim(data->>'transactionNumber')));
CREATE UNIQUE INDEX IF NOT EXISTS inventory_generator_date_unique ON public.generator_logs ((data->>'date'));
CREATE INDEX IF NOT EXISTS inventory_ledger_item_warehouse_date ON public.transactions ((data->>'itemId'), (data->>'storehouseId'), (data->>'date'));

-- R8-CODE-01: permanent reservation of every material code ever used (active, archived or deleted).
-- Private schema only: no client grant, written exclusively inside commit_inventory.
CREATE TABLE IF NOT EXISTS inventory_private.material_code_registry(
  code_key text PRIMARY KEY,
  code text NOT NULL,
  prefix text,
  number numeric,
  material_id text NOT NULL,
  source text NOT NULL,
  reserved_at timestamptz NOT NULL DEFAULT now(),
  -- R8-R1 (R2-R8-04): set when the owning material is deleted; a deleted reservation is never re-issued, not even to the same id.
  deleted_at timestamptz
);
CREATE UNIQUE INDEX IF NOT EXISTS material_code_registry_prefix_number ON inventory_private.material_code_registry(prefix, number) WHERE prefix IS NOT NULL;
ALTER TABLE inventory_private.material_code_registry ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
REVOKE ALL ON TABLE inventory_private.material_code_registry FROM PUBLIC, anon, authenticated;

-- R8-R1 (R2-R8-03 / RT-R8-06): the owner-approved category policy is pinned at the server. After the migration the
-- five prefixes and their exact ranges can be neither removed, re-ranged (shrunk, widened, overlapped) nor
-- supplemented; only category display names may change. A policy change needs a separately approved SQL migration.
CREATE TABLE IF NOT EXISTS inventory_private.category_policy(
  prefix text PRIMARY KEY CHECK (prefix ~ '^[A-Z]{2,6}$'),
  start_range numeric NOT NULL,
  end_range numeric NOT NULL,
  pinned_at timestamptz NOT NULL DEFAULT now(),
  CHECK (start_range>=1 AND start_range<=end_range)
);
REVOKE ALL ON TABLE inventory_private.category_policy FROM PUBLIC, anon, authenticated;
INSERT INTO inventory_private.category_policy(prefix,start_range,end_range)
VALUES ('PES',1001,1999),('SAN',2001,2999),('EQP',3001,3999),('ROD',4001,4999),('CHM',5001,5999)
ON CONFLICT(prefix) DO NOTHING;

CREATE OR REPLACE FUNCTION inventory_private.derived_material_keys() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT ARRAY['currentStock','warehouseStocks','warehouseStocksById','ledgerTotalStock']::text[] $$;
CREATE OR REPLACE FUNCTION inventory_private.lifecycle_material_keys() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT ARRAY['lifecycleStatus','lifecycleVersion','archivedAt','archivedBy','archivedByName','archiveReason','archivePurpose','reactivatedAt','reactivatedBy','reactivatedByName','reactivationReason']::text[] $$;
CREATE OR REPLACE FUNCTION inventory_private.server_owned_material_keys() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT inventory_private.derived_material_keys() || inventory_private.lifecycle_material_keys() $$;

-- Canonical code form: PREFIX-N (uppercase prefix, no leading zero). Returns NULL parts for legacy codes.
CREATE OR REPLACE FUNCTION inventory_private.code_parts(p_code text) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT CASE WHEN btrim(coalesce(p_code,'')) ~ '^[A-Za-z]{2,6}-[1-9][0-9]{0,8}$'
   THEN jsonb_build_object('prefix',upper(split_part(btrim(p_code),'-',1)),'number',split_part(btrim(p_code),'-',2)::numeric)
   ELSE jsonb_build_object('prefix',NULL,'number',NULL) END
$$;

-- R8-DATA-01: ledger-derived projection of ONE material.
--   warehouseStocksById : canonical, every warehouse (active or not) that has ledger effects, by stable id
--   ledgerTotalStock    : total across ALL warehouses (historical/all-ledger total; never loses stock of a disabled warehouse)
--   currentStock        : active-warehouse display total (same definition as the client getMaterials view)
--   warehouseStocks     : name-keyed compatibility map for ACTIVE warehouses only
-- Opening fallback: initialStock counts once at the primary warehouse only when no opening row exists.
CREATE OR REPLACE FUNCTION inventory_private.material_projection(p_id text) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = '' AS $$
 WITH cfg AS (SELECT data FROM public.settings WHERE id='app_config'),
 wh AS (SELECT w->>'id' wid, w->>'name' wname, coalesce((w->>'active')::boolean,false) active FROM cfg, jsonb_array_elements(coalesce(cfg.data->'storehouseEntities','[]')) w),
 m AS (SELECT data FROM public.materials WHERE id=p_id),
 eff AS (
   SELECT t.data->>'storehouseId' wid,
     (t.data->>'quantity')::numeric * CASE WHEN t.data->>'transactionType' IN ('وارد','افتتاحي')
       OR (t.data->>'transactionType' IN ('تسوية','تحويل') AND t.data->>'transferType'='in') THEN 1 ELSE -1 END q
   FROM public.transactions t WHERE t.data->>'itemId'=p_id
   UNION ALL
   SELECT m.data->>'primaryStorehouseId', coalesce((m.data->>'initialStock')::numeric,0) FROM m
   WHERE coalesce((m.data->>'initialStock')::numeric,0)>0
     AND NOT EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'itemId'=p_id AND (t.data->>'transactionType'='افتتاحي' OR t.id LIKE 'tr-init%'))
 ), bal AS (SELECT wid, sum(q) q FROM eff WHERE wid IS NOT NULL GROUP BY wid)
 SELECT jsonb_build_object(
   'warehouseStocksById', coalesce((SELECT jsonb_object_agg(bal.wid, bal.q) FROM bal),'{}'::jsonb),
   'warehouseStocks', coalesce((SELECT jsonb_object_agg(wh.wname, bal.q) FROM bal JOIN wh ON wh.wid=bal.wid WHERE wh.active),'{}'::jsonb),
   'currentStock', coalesce((SELECT sum(bal.q) FROM bal JOIN wh ON wh.wid=bal.wid WHERE wh.active),0),
   'ledgerTotalStock', coalesce((SELECT sum(bal.q) FROM bal),0))
$$;

CREATE OR REPLACE FUNCTION inventory_private.material_ledger_hash(p_id text) RETURNS text
LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT encode(sha256(convert_to(coalesce((SELECT jsonb_agg(jsonb_build_array(t.id,t.data) ORDER BY t.id) FROM public.transactions t WHERE t.data->>'itemId'=p_id)::text,'[]'),'UTF8')),'hex')
$$;

CREATE OR REPLACE FUNCTION inventory_private.stored_projection(p_data jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT coalesce((SELECT jsonb_object_agg(k, p_data->k) FROM unnest(inventory_private.derived_material_keys()) k WHERE p_data ? k),'{}'::jsonb)
$$;

-- R8-R1 (RT-R8-02): 'drift' = a stored derived value disagrees with the ledger. Such a material is never corrected
-- silently by an ordinary commit; only the explicit, audited reconcile mode may rewrite it.
CREATE OR REPLACE FUNCTION inventory_private.projection_status(p_data jsonb, p_computed jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT CASE WHEN inventory_private.stored_projection(p_data)='{}'::jsonb THEN 'unprojected'
   WHEN EXISTS(SELECT 1 FROM jsonb_each(inventory_private.stored_projection(p_data)) s WHERE s.value IS DISTINCT FROM p_computed->s.key) THEN 'drift'
   WHEN inventory_private.stored_projection(p_data)<>p_computed THEN 'incomplete' ELSE 'ok' END
$$;

CREATE OR REPLACE FUNCTION inventory_private.material_rows(p_ids jsonb) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT coalesce(jsonb_agg(m.data ORDER BY m.id),'[]'::jsonb) FROM public.materials m
 WHERE jsonb_typeof(p_ids)='array' AND m.id IN (SELECT jsonb_array_elements_text(p_ids))
$$;

-- R8-CODE-01 / CFG-02: category configuration is validated at the server on every commit.
CREATE OR REPLACE FUNCTION inventory_private.validate_category_config(p_cfg jsonb) RETURNS void
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
 IF jsonb_typeof(p_cfg->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(p_cfg->'categories')=0
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c WHERE jsonb_typeof(c) IS DISTINCT FROM 'object'
       OR nullif(btrim(c->>'name'),'') IS NULL OR c->>'name'<>btrim(c->>'name')
       OR coalesce(c->>'prefix','') !~ '^[A-Z]{2,6}$'
       OR jsonb_typeof(c->'startRange') IS DISTINCT FROM 'number' OR jsonb_typeof(c->'endRange') IS DISTINCT FROM 'number'
       OR (c->>'startRange')::numeric<>trunc((c->>'startRange')::numeric) OR (c->>'endRange')::numeric<>trunc((c->>'endRange')::numeric)
       OR (c->>'startRange')::numeric<1 OR (c->>'endRange')::numeric>999999999 OR (c->>'startRange')::numeric>(c->>'endRange')::numeric)
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_CONFIG_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c GROUP BY lower(regexp_replace(btrim(c->>'name'),'\s+',' ','g')) HAVING count(*)>1)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c GROUP BY c->>'prefix' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_DUPLICATE' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') WITH ORDINALITY a(c,i), jsonb_array_elements(p_cfg->'categories') WITH ORDINALITY b(c,j)
     WHERE a.i<b.j AND (a.c->>'startRange')::numeric<=(b.c->>'endRange')::numeric AND (b.c->>'startRange')::numeric<=(a.c->>'endRange')::numeric)
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_RANGE_OVERLAP' USING ERRCODE='23514'; END IF;
 -- Freeze after first use: a used prefix cannot disappear, and its range cannot shrink below any reserved number.
 IF EXISTS(SELECT 1 FROM (SELECT prefix, min(number) lo, max(number) hi FROM inventory_private.material_code_registry WHERE prefix IS NOT NULL GROUP BY prefix) r
     WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c WHERE c->>'prefix'=r.prefix
       AND (c->>'startRange')::numeric<=r.lo AND (c->>'endRange')::numeric>=r.hi))
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_PREFIX_FROZEN' USING ERRCODE='23514'; END IF;
 -- R8-R1 (R2-R8-03): the pinned policy is exact: every pinned prefix with exactly its range, and nothing else.
 IF EXISTS(SELECT 1 FROM inventory_private.category_policy) AND (
      EXISTS(SELECT 1 FROM inventory_private.category_policy p WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c
        WHERE c->>'prefix'=p.prefix AND (c->>'startRange')::numeric=p.start_range AND (c->>'endRange')::numeric=p.end_range))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c WHERE NOT EXISTS(SELECT 1 FROM inventory_private.category_policy p WHERE p.prefix=c->>'prefix')))
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_POLICY_PINNED' USING ERRCODE='23514'; END IF;
END;
$$;

CREATE OR REPLACE FUNCTION inventory_private.code_matches_category(p_code text, p_category text, p_cfg jsonb) RETURNS boolean
LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT p_code = btrim(p_code) AND p_code ~ '^[A-Z]{2,6}-[1-9][0-9]{0,8}$' AND EXISTS(
   SELECT 1 FROM jsonb_array_elements(p_cfg->'categories') c WHERE c->>'name'=p_category AND c->>'prefix'=split_part(p_code,'-',1)
     AND split_part(p_code,'-',2)::numeric BETWEEN (c->>'startRange')::numeric AND (c->>'endRange')::numeric)
$$;

-- Registers a material code permanently. p_strict: create/code change/category change (always checks membership);
-- non-strict (restore/import of an already registered code) checks membership only for unregistered codes.
-- R8-R1 (RT-R8-03 / R2-R8-04): outside restore, a NEW canonical code must be exactly the next central number of its
-- prefix (registry maximum + 1), so a manual, imported or crafted RPC code can neither skip ahead nor exhaust a range;
-- and a reservation whose material was deleted is never issued again, not even to a re-created material with the same id.
CREATE OR REPLACE FUNCTION inventory_private.reserve_material_code(p_id text, p_data jsonb, p_cfg jsonb, p_strict boolean, p_source text) RETURNS void
LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE k text:=lower(btrim(coalesce(p_data->>'code',''))); parts jsonb; registered boolean; nxt numeric; c jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM inventory_private.material_code_registry r WHERE r.code_key=k
      AND (r.material_id<>p_id OR (r.deleted_at IS NOT NULL AND p_source<>'restore')))
    OR EXISTS(SELECT 1 FROM public.materials m WHERE m.id<>p_id AND lower(btrim(m.data->>'code'))=k)
 THEN RAISE EXCEPTION 'INVENTORY_CODE_RESERVED:%',p_data->>'code' USING ERRCODE='23505'; END IF;
 registered:=EXISTS(SELECT 1 FROM inventory_private.material_code_registry r WHERE r.code_key=k AND r.material_id=p_id);
 IF (p_strict OR NOT registered) AND NOT inventory_private.code_matches_category(p_data->>'code',p_data->>'category',p_cfg)
 THEN RAISE EXCEPTION 'INVENTORY_CODE_CATEGORY_MISMATCH:%',p_data->>'code' USING ERRCODE='23514'; END IF;
 parts:=inventory_private.code_parts(p_data->>'code');
 IF parts->>'prefix' IS NOT NULL AND EXISTS(SELECT 1 FROM inventory_private.material_code_registry r WHERE r.prefix=parts->>'prefix' AND r.number=(parts->>'number')::numeric
      AND (r.material_id<>p_id OR (r.deleted_at IS NOT NULL AND p_source<>'restore')))
 THEN RAISE EXCEPTION 'INVENTORY_CODE_RESERVED:%',p_data->>'code' USING ERRCODE='23505'; END IF;
 IF NOT registered AND p_source<>'restore' AND parts->>'prefix' IS NOT NULL THEN
   SELECT x INTO c FROM jsonb_array_elements(p_cfg->'categories') x WHERE x->>'prefix'=parts->>'prefix';
   -- one past the highest REGISTERED number of the prefix (the migration backfills every existing code, so the registry
   -- is the single source; next_material_code() suggests the same value)
   nxt:=greatest(coalesce((c->>'startRange')::numeric,1)-1,
     coalesce((SELECT max(r.number) FROM inventory_private.material_code_registry r WHERE r.prefix=parts->>'prefix'),0))+1;
   IF (parts->>'number')::numeric<>nxt THEN
     RAISE EXCEPTION 'INVENTORY_CODE_NOT_NEXT:%:%',p_data->>'code',(parts->>'prefix')||'-'||nxt::text USING ERRCODE='23514';
   END IF;
 END IF;
 INSERT INTO inventory_private.material_code_registry(code_key,code,prefix,number,material_id,source)
 VALUES(k,btrim(p_data->>'code'),parts->>'prefix',(parts->>'number')::numeric,p_id,p_source)
 ON CONFLICT(code_key) DO UPDATE SET deleted_at=NULL
   WHERE inventory_private.material_code_registry.material_id=excluded.material_id AND p_source='restore';
END;
$$;

-- One-time idempotent backfill: every existing code is reserved for its current material (legacy codes keep NULL prefix).
INSERT INTO inventory_private.material_code_registry(code_key,code,prefix,number,material_id,source)
SELECT lower(btrim(m.data->>'code')),btrim(m.data->>'code'),
  CASE WHEN p->>'prefix' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.materials o WHERE o.id<>m.id AND (inventory_private.code_parts(o.data->>'code'))=p) THEN p->>'prefix' END,
  CASE WHEN p->>'prefix' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.materials o WHERE o.id<>m.id AND (inventory_private.code_parts(o.data->>'code'))=p) THEN (p->>'number')::numeric END,
  m.id,'r8-backfill'
FROM public.materials m CROSS JOIN LATERAL inventory_private.code_parts(m.data->>'code') p
WHERE nullif(btrim(m.data->>'code'),'') IS NOT NULL
ON CONFLICT(code_key) DO NOTHING;

CREATE OR REPLACE FUNCTION inventory_private.state_hash() RETURNS text
LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_array(collection,id,x) ORDER BY collection,id)::text,'[]'),'UTF8')),'hex')
 FROM (SELECT 'materials' collection,id,data x FROM public.materials
       UNION ALL SELECT 'transactions',id,data FROM public.transactions
       UNION ALL SELECT 'generator_logs',id,data FROM public.generator_logs
       UNION ALL SELECT 'settings',id,data FROM public.settings
       UNION ALL SELECT 'users',id,data FROM public.users) s;
$$;

CREATE OR REPLACE FUNCTION inventory_private.validate_inventory() RETURNS void
LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE cfg jsonb; row_data jsonb; v_date text;
BEGIN
 SELECT data INTO cfg FROM public.settings WHERE id='app_config';
 IF cfg IS NULL OR jsonb_typeof(cfg->'storehouseEntities') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'storehouseEntities')=0
    OR jsonb_typeof(cfg->'units') IS DISTINCT FROM 'array' OR jsonb_typeof(cfg->'categories') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'INVENTORY_SETTINGS_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w
           WHERE nullif(btrim(w->>'id'),'') IS NULL OR nullif(btrim(w->>'name'),'') IS NULL OR jsonb_typeof(w->'active') IS DISTINCT FROM 'boolean')
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w GROUP BY w->>'id' HAVING count(*)>1)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w GROUP BY lower(btrim(w->>'name')) HAVING count(*)>1)
 THEN RAISE EXCEPTION 'INVENTORY_WAREHOUSE_INVALID' USING ERRCODE='23514'; END IF;
 -- R8-CODE-01 / CFG-02: category configuration and referenced-category removal.
 PERFORM inventory_private.validate_category_config(cfg);
 IF EXISTS(SELECT 1 FROM public.materials m WHERE nullif(btrim(m.data->>'category'),'') IS NOT NULL
     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'categories') c WHERE c->>'name'=m.data->>'category'))
 THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_IN_USE' USING ERRCODE='23514'; END IF;
 -- R8-ARC-01: lifecycle is either absent/active or a complete archived record.
 IF EXISTS(SELECT 1 FROM public.materials m WHERE coalesce(m.data->>'lifecycleStatus','active') NOT IN ('active','archived')
     OR (m.data->>'lifecycleStatus'='archived' AND (nullif(m.data->>'archivedAt','') IS NULL OR nullif(m.data->>'archivedBy','') IS NULL))
     OR (m.data ? 'lifecycleVersion' AND (jsonb_typeof(m.data->'lifecycleVersion') IS DISTINCT FROM 'number' OR (m.data->>'lifecycleVersion')::numeric<0)))
 THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.materials m WHERE nullif(btrim(m.data->>'code'),'') IS NULL
     OR nullif(btrim(m.data->>'name'),'') IS NULL OR nullif(btrim(m.data->>'category'),'') IS NULL
     OR nullif(btrim(m.data->>'unit'),'') IS NULL OR m.data->>'id' IS DISTINCT FROM m.id
     OR jsonb_typeof(m.data->'minimumStock') IS DISTINCT FROM 'number' OR (m.data->>'minimumStock')::numeric<0
     OR (m.data ? 'initialStock' AND (jsonb_typeof(m.data->'initialStock') IS DISTINCT FROM 'number' OR (m.data->>'initialStock')::numeric<0))
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w WHERE w->>'id'=m.data->>'primaryStorehouseId')
     OR NOT (cfg->'units' @> jsonb_build_array(m.data->>'unit'))
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'categories') c WHERE c->>'name'=m.data->>'category'))
 THEN RAISE EXCEPTION 'INVENTORY_MATERIAL_INVALID' USING ERRCODE='23514'; END IF;
 -- R8-R1 (RT-R8-06): a canonical code of a pinned prefix must stay inside its own category (no name swap/remap).
 IF EXISTS(SELECT 1 FROM public.materials m CROSS JOIN LATERAL inventory_private.code_parts(m.data->>'code') p
     WHERE p->>'prefix' IN (SELECT cp.prefix FROM inventory_private.category_policy cp)
       AND NOT inventory_private.code_matches_category(upper(btrim(m.data->>'code')),m.data->>'category',cfg))
 THEN RAISE EXCEPTION 'INVENTORY_CODE_CATEGORY_MISMATCH' USING ERRCODE='23514'; END IF;
 FOR row_data IN SELECT data FROM public.transactions LOOP
   v_date:=row_data->>'date';
   IF v_date IS NULL OR v_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(v_date::date,'YYYY-MM-DD')<>v_date
   THEN RAISE EXCEPTION 'INVENTORY_DATE_INVALID' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'id' IS DISTINCT FROM t.id
     OR nullif(btrim(t.data->>'transactionNumber'),'') IS NULL
     OR jsonb_typeof(t.data->'quantity') IS DISTINCT FROM 'number' OR (t.data->>'quantity')::numeric<=0
     OR coalesce(t.data->>'transactionType','') NOT IN ('وارد','صادر','مستهلك','افتتاحي','تسوية','تحويل')
     OR (t.data->>'transactionType' IN ('تسوية','تحويل') AND coalesce(t.data->>'transferType','') NOT IN ('in','out'))
     OR NOT EXISTS(SELECT 1 FROM public.materials m WHERE m.id=t.data->>'itemId')
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w WHERE w->>'id'=t.data->>'storehouseId'))
 THEN RAISE EXCEPTION 'INVENTORY_TRANSACTION_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'transactionType'='تحويل' AND
    (nullif(t.data->>'operationId','') IS NULL OR NOT EXISTS(
      SELECT 1 FROM public.transactions p WHERE p.id=t.data->>'pairedTransactionId'
      AND p.data->>'pairedTransactionId'=t.id AND p.data->>'operationId'=t.data->>'operationId'
      AND p.data->>'transactionType'='تحويل' AND p.data->>'itemId'=t.data->>'itemId'
      AND p.data->>'date'=t.data->>'date' AND p.data->'quantity'=t.data->'quantity'
      AND p.data->>'storehouseId'<>t.data->>'storehouseId' AND p.data->>'transferType'<>t.data->>'transferType')))
    OR EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'transactionType'='تحويل' GROUP BY t.data->>'operationId' HAVING count(*)<>2)
 THEN RAISE EXCEPTION 'INVENTORY_TRANSFER_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(
   WITH effects AS (
     SELECT t.id,t.data->>'itemId' item,t.data->>'storehouseId' warehouse,t.data->>'date' dt,
       coalesce(t.data->>'createdAt','') created,
       (t.data->>'quantity')::numeric * CASE WHEN t.data->>'transactionType' IN ('وارد','افتتاحي')
         OR (t.data->>'transactionType' IN ('تسوية','تحويل') AND t.data->>'transferType'='in') THEN 1 ELSE -1 END delta
     FROM public.transactions t
     UNION ALL
     SELECT '',m.id,m.data->>'primaryStorehouseId','0000-01-01','',coalesce((m.data->>'initialStock')::numeric,0)
     FROM public.materials m WHERE NOT EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'itemId'=m.id AND (t.data->>'transactionType'='افتتاحي' OR t.id LIKE 'tr-init%'))
   ), balances AS (SELECT sum(delta) OVER(PARTITION BY item,warehouse ORDER BY dt,created,id ROWS UNBOUNDED PRECEDING) balance FROM effects)
   SELECT 1 FROM balances WHERE balance < -0.000000001
 ) THEN RAISE EXCEPTION 'INVENTORY_NEGATIVE_BALANCE' USING ERRCODE='23514'; END IF;
 FOR row_data IN SELECT data FROM public.generator_logs LOOP
   v_date:=row_data->>'date';
   IF v_date IS NULL OR v_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(v_date::date,'YYYY-MM-DD')<>v_date
      OR jsonb_typeof(row_data->'currentReading') IS DISTINCT FROM 'number'
      OR jsonb_typeof(row_data->'previousReading') IS DISTINCT FROM 'number'
      OR jsonb_typeof(row_data->'operatingHours') IS DISTINCT FROM 'number'
      OR (row_data->>'previousReading')::numeric<0 OR (row_data->>'currentReading')::numeric<(row_data->>'previousReading')::numeric
      OR abs((row_data->>'operatingHours')::numeric-((row_data->>'currentReading')::numeric-(row_data->>'previousReading')::numeric))>0.000000001
   THEN RAISE EXCEPTION 'INVENTORY_GENERATOR_INVALID' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM(SELECT data,lag((data->>'currentReading')::numeric) OVER(ORDER BY data->>'date',id) previous FROM public.generator_logs) g
           WHERE previous IS NOT NULL AND abs(previous-(data->>'previousReading')::numeric)>0.000000001)
 THEN RAISE EXCEPTION 'INVENTORY_GENERATOR_CHAIN_INVALID' USING ERRCODE='23514'; END IF;
END;
$$;

CREATE OR REPLACE FUNCTION inventory_private.commit_inventory(p_mutation_id text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor public.users%ROWTYPE; op jsonb; ops jsonb; receipt jsonb; digest text; old jsonb; val jsonb;
 col text; doc text; kind text; needed text; mode text; stamp text; saved public.audit_logs%ROWTYPE;
 affected jsonb:='[]'; results jsonb:='[]'; removed jsonb:='[]'; corr jsonb:='[]'; cfg jsonb; backup jsonb; entry jsonb; old_permissions jsonb;
 owned text[]:=inventory_private.server_owned_material_keys(); derived text[]:=inventory_private.derived_material_keys();
 lc_keys text[]:=inventory_private.lifecycle_material_keys();
 touched text[]:='{}'; ledger_items text[]:='{}'; strict_codes text[]:='{}'; restore_codes text[]:='{}'; all_materials boolean:=false;
 proj_ids text[]; proj_changes jsonb:='[]'; extra jsonb:='{}'; lc jsonb; cur_lc jsonb:='{}'; lc_preserved jsonb:='[]';
 mid text; before_d jsonb; after_d jsonb; lc_from text; lc_ver numeric; total numeric; business_equal boolean;
 pre_drift text[]:='{}'; direct text[]:='{}'; held jsonb:='[]'; is_admin boolean;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'INVENTORY_AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 -- One short serializable writer boundary. This also fences permission revocation through users.
 PERFORM pg_advisory_xact_lock(824671520);
 SELECT * INTO actor FROM public.users WHERE auth_uid=auth.uid()::text AND active FOR UPDATE;
 IF actor.id IS NULL THEN RAISE EXCEPTION 'INVENTORY_ACCOUNT_DISABLED' USING ERRCODE='42501'; END IF;
 IF p_mutation_id IS NULL OR p_mutation_id !~ '^[A-Za-z0-9:_-]{8,160}$' OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
    OR octet_length(p_payload::text)>4000000 THEN RAISE EXCEPTION 'INVENTORY_ENVELOPE_INVALID' USING ERRCODE='22023'; END IF;
 digest:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
 SELECT * INTO saved FROM public.audit_logs WHERE id=p_mutation_id;
 IF FOUND THEN
   IF saved.data->>'actorUserId'<>actor.id OR saved.data->>'mutationDigest' IS DISTINCT FROM digest
   THEN RAISE EXCEPTION 'INVENTORY_MUTATION_ID_REUSED' USING ERRCODE='23505'; END IF;
   -- Replay returns the ORIGINAL receipt; no new effect. Current server projections are attached for the client view.
   RETURN jsonb_build_object('audit',saved.data,'replayed',true,'results',coalesce(saved.data->'mutationResults','[]'),
     'materials',inventory_private.material_rows(saved.data->'projectedMaterialIds'));
 END IF;
 stamp:=to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 mode:=coalesce(p_payload->>'mode','mutation'); ops:=p_payload->'operations';

 -- R8-ARC-01: reversible logical archive / reactivation. Dedicated mode, explicit capability, expected version.
 IF mode='lifecycle' THEN
   IF NOT actor.permissions ? 'materials_archive' THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_DENIED' USING ERRCODE='42501'; END IF;
   lc:=p_payload->'lifecycle';
   IF jsonb_typeof(lc) IS DISTINCT FROM 'object' OR coalesce(lc->>'action','') NOT IN ('archive','reactivate')
      OR nullif(btrim(lc->>'materialId'),'') IS NULL OR jsonb_typeof(lc->'expectedLifecycleVersion') IS DISTINCT FROM 'number'
      OR nullif(btrim(lc->>'reason'),'') IS NULL
      OR (lc->>'action'='archive' AND coalesce(lc->>'purpose','') NOT IN ('qa_test_data','discontinued'))
   THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_INVALID' USING ERRCODE='22023'; END IF;
   mid:=lc->>'materialId';
   SELECT data INTO old FROM public.materials WHERE id=mid FOR UPDATE;
   IF old IS NULL THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_MISSING' USING ERRCODE='40001'; END IF;
   lc_ver:=coalesce((old->>'lifecycleVersion')::numeric,0); lc_from:=coalesce(old->>'lifecycleStatus','active');
   IF (lc->>'expectedLifecycleVersion')::numeric<>lc_ver THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_STALE' USING ERRCODE='40001'; END IF;
   IF (lc->>'action'='archive' AND lc_from='archived') OR (lc->>'action'='reactivate' AND lc_from<>'archived')
   THEN RAISE EXCEPTION 'INVENTORY_LIFECYCLE_STATE_INVALID' USING ERRCODE='23514'; END IF;
   after_d:=inventory_private.material_projection(mid); total:=(after_d->>'ledgerTotalStock')::numeric;
   -- R8-R1 (RT-R8-02): a drifted stored projection is never corrected as a side effect; reconcile first.
   IF inventory_private.projection_status(old,after_d)='drift'
   THEN RAISE EXCEPTION 'INVENTORY_RECONCILE_REQUIRED:%',old->>'code' USING ERRCODE='23514'; END IF;
   -- R8-R1 (R2-R8-01): archive is not a disposal. A material whose ledger total is not zero can never be archived,
   -- whatever the declared purpose (the purpose is a client label, not an authorization).
   IF lc->>'action'='archive' AND total<>0
   THEN RAISE EXCEPTION 'INVENTORY_ARCHIVE_NONZERO_STOCK' USING ERRCODE='23514'; END IF;
   val:=(old-lc_keys-derived)||after_d||CASE WHEN lc->>'action'='archive' THEN jsonb_build_object('lifecycleStatus','archived','lifecycleVersion',lc_ver+1,
       'archivedAt',stamp,'archivedBy',actor.id,'archivedByName',actor.full_name,'archiveReason',left(lc->>'reason',500),'archivePurpose',lc->>'purpose')
     ELSE jsonb_build_object('lifecycleStatus','active','lifecycleVersion',lc_ver+1,'reactivatedAt',stamp,'reactivatedBy',actor.id,
       'reactivatedByName',actor.full_name,'reactivationReason',left(lc->>'reason',500)) END;
   UPDATE public.materials SET data=val,updated_at=now() WHERE id=mid;
   PERFORM inventory_private.validate_inventory();
   receipt:=jsonb_build_object('id',p_mutation_id,'timestamp',stamp,'user',actor.full_name,'actorUserId',actor.id,'actorDisplayName',actor.full_name,
     'action',CASE WHEN lc->>'action'='archive' THEN 'أرشفة صنف (أرشفة منطقية قابلة للعكس)' ELSE 'إعادة تفعيل صنف مؤرشف' END,
     'details',left(format('%s %s — السبب: %s',CASE WHEN lc->>'action'='archive' THEN 'أرشفة' ELSE 'إعادة تفعيل' END,old->>'code',lc->>'reason'),8000),
     'itemType','مادة','operationType','system','affectedEntities',jsonb_build_array('materials/'||mid),'result','committed',
     'mutationDigest',digest,'mutationLabel',left(p_payload->>'label',160),'projectedMaterialIds',jsonb_build_array(mid),
     'lifecycle',jsonb_build_object('action',lc->>'action','materialId',mid,'code',old->>'code','fromStatus',lc_from,'toStatus',val->>'lifecycleStatus',
       'fromVersion',lc_ver,'toVersion',lc_ver+1,'reason',left(lc->>'reason',500),'purpose',lc->>'purpose','ledgerTotalStock',total,
       'ledgerRows',(SELECT count(*) FROM public.transactions t WHERE t.data->>'itemId'=mid),'ledgerHash',inventory_private.material_ledger_hash(mid)));
   INSERT INTO public.audit_logs(id,data,updated_at) VALUES(p_mutation_id,receipt,now());
   RETURN jsonb_build_object('audit',receipt,'replayed',false,'results','[]'::jsonb,'materials',jsonb_build_array(val));
 END IF;

 -- R8-DATA-01: audited reconcile of DERIVED fields only, pinned to the exact stored document (and optionally its ledger hash).
 IF mode='reconcile' THEN
   IF NOT (actor.permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb)
   THEN RAISE EXCEPTION 'INVENTORY_RECONCILE_DENIED' USING ERRCODE='42501'; END IF;
   lc:=p_payload->'reconcile';
   IF jsonb_typeof(lc->'materials') IS DISTINCT FROM 'array' OR jsonb_array_length(lc->'materials')=0 OR jsonb_array_length(lc->'materials')>450
      OR nullif(btrim(lc->>'reason'),'') IS NULL
   THEN RAISE EXCEPTION 'INVENTORY_RECONCILE_INVALID' USING ERRCODE='22023'; END IF;
   FOR entry IN SELECT value FROM jsonb_array_elements(lc->'materials') LOOP
     mid:=entry->>'id';
     SELECT data INTO old FROM public.materials WHERE id=mid FOR UPDATE;
     IF old IS NULL OR entry->'expected' IS DISTINCT FROM old
        OR (entry ? 'expectedLedgerHash' AND entry->>'expectedLedgerHash' IS DISTINCT FROM inventory_private.material_ledger_hash(mid))
     THEN RAISE EXCEPTION 'INVENTORY_RECONCILE_STALE' USING ERRCODE='40001'; END IF;
     before_d:=inventory_private.stored_projection(old); after_d:=inventory_private.material_projection(mid);
     UPDATE public.materials SET data=(data-derived)||after_d,updated_at=now() WHERE id=mid;
     proj_changes:=proj_changes||jsonb_build_array(jsonb_build_object('id',mid,'code',old->>'code','before',before_d,'after',after_d,
       'ledgerRows',(SELECT count(*) FROM public.transactions t WHERE t.data->>'itemId'=mid),'ledgerHash',inventory_private.material_ledger_hash(mid)));
     affected:=affected||jsonb_build_array('materials/'||mid);
   END LOOP;
   PERFORM inventory_private.validate_inventory();
   receipt:=jsonb_build_object('id',p_mutation_id,'timestamp',stamp,'user',actor.full_name,'actorUserId',actor.id,'actorDisplayName',actor.full_name,
     'action','مصالحة الأرصدة المشتقة مع دفتر الحركات','details',left('تحديث الحقول المشتقة فقط؛ لم تتغير الحركات ولا العدادات. السبب: '||(lc->>'reason'),8000),
     'itemType','مادة','operationType','system','affectedEntities',affected,'result','committed','mutationDigest',digest,
     'mutationLabel',left(p_payload->>'label',160),'reconciliations',proj_changes,
     'projectedMaterialIds',(SELECT jsonb_agg(x->>'id') FROM jsonb_array_elements(proj_changes) x));
   INSERT INTO public.audit_logs(id,data,updated_at) VALUES(p_mutation_id,receipt,now());
   RETURN jsonb_build_object('audit',receipt,'replayed',false,'results','[]'::jsonb,'materials',inventory_private.material_rows(receipt->'projectedMaterialIds'));
 END IF;

 IF mode='restore' THEN
   IF NOT (actor.permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb)
   THEN RAISE EXCEPTION 'INVENTORY_RESTORE_DENIED' USING ERRCODE='42501'; END IF;
   IF p_payload->>'expectedState' IS DISTINCT FROM inventory_private.state_hash()
   THEN RAISE EXCEPTION 'INVENTORY_RESTORE_STALE' USING ERRCODE='40001'; END IF;
   backup:=p_payload->'backup';
   IF jsonb_typeof(backup->'materials') IS DISTINCT FROM 'array' OR jsonb_typeof(backup->'transactions') IS DISTINCT FROM 'array'
      OR jsonb_typeof(backup->'generatorLogs') IS DISTINCT FROM 'array' OR jsonb_typeof(backup->'users') IS DISTINCT FROM 'array' OR jsonb_typeof(backup->'settings') IS DISTINCT FROM 'object'
   THEN RAISE EXCEPTION 'INVENTORY_BACKUP_INVALID' USING ERRCODE='22023'; END IF;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(backup->'users') u WHERE u->>'id'=actor.id
       AND u->>'authUid'=actor.auth_uid AND u->'active'='true'::jsonb AND u->'permissions' @> '["users_manage","settings_edit","system_reset"]'::jsonb)
   THEN RAISE EXCEPTION 'INVENTORY_RESTORE_WOULD_LOCK_ADMIN' USING ERRCODE='23514'; END IF;
   -- R8-ARC-01/REC-01: remember current lifecycle so an older snapshot cannot silently reactivate an archived item.
   SELECT coalesce(jsonb_object_agg(id,data),'{}'::jsonb) INTO cur_lc FROM public.materials WHERE data ? 'lifecycleStatus' OR data ? 'lifecycleVersion';
   -- Authentication identities and immutable audit history are never restored/deleted.
   DELETE FROM public.transactions; DELETE FROM public.materials; DELETE FROM public.generator_logs;
   DELETE FROM public.users WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(backup->'users') u WHERE u->>'id'=public.users.id);
   ops:='[]';
   FOR col IN SELECT unnest(ARRAY['settings','materials','transactions','generator_logs','users']) LOOP
     FOR val IN SELECT value FROM jsonb_array_elements(CASE col WHEN 'settings' THEN jsonb_build_array((backup->'settings')||'{"id":"app_config"}')
       WHEN 'generator_logs' THEN backup->'generatorLogs' ELSE backup->col END) LOOP
       IF col='materials' AND jsonb_typeof(val)='object' THEN
         val:=val-derived; -- derived values in a backup are never authoritative; recomputed below.
         IF cur_lc ? (val->>'id') THEN
           entry:=cur_lc->(val->>'id');
           IF NOT val ? 'lifecycleStatus' THEN
             IF entry->>'lifecycleStatus'='archived' THEN
               val:=(val-lc_keys)||coalesce((SELECT jsonb_object_agg(k,entry->k) FROM unnest(lc_keys) k WHERE entry ? k),'{}'::jsonb);
               lc_preserved:=lc_preserved||jsonb_build_array(val->>'id');
             END IF;
           ELSIF coalesce((val->>'lifecycleVersion')::numeric,0)<coalesce((entry->>'lifecycleVersion')::numeric,0) THEN
             RAISE EXCEPTION 'INVENTORY_RESTORE_LIFECYCLE_STALE' USING ERRCODE='40001';
           END IF;
         END IF;
         restore_codes:=restore_codes||(val->>'id');
       END IF;
       ops:=ops||jsonb_build_array(jsonb_build_object('collection',col,'docId',val->>'id','kind','set','value',val));
     END LOOP;
   END LOOP;
   all_materials:=true;
   -- R8-R1 (RT-R8-04): reservations carried by the backup are merged union-only (never dropped, never re-owned).
   IF backup ? 'codeRegistry' THEN
     IF jsonb_typeof(backup->'codeRegistry') IS DISTINCT FROM 'array' OR jsonb_array_length(backup->'codeRegistry')>100000
        OR EXISTS(SELECT 1 FROM jsonb_array_elements(backup->'codeRegistry') r WHERE jsonb_typeof(r) IS DISTINCT FROM 'object'
          OR nullif(btrim(r->>'code'),'') IS NULL OR length(r->>'code')>120 OR nullif(btrim(r->>'materialId'),'') IS NULL OR length(r->>'materialId')>200)
     THEN RAISE EXCEPTION 'INVENTORY_BACKUP_INVALID' USING ERRCODE='22023'; END IF;
     INSERT INTO inventory_private.material_code_registry(code_key,code,prefix,number,material_id,source,deleted_at)
     SELECT lower(btrim(r->>'code')),btrim(r->>'code'),p->>'prefix',(p->>'number')::numeric,r->>'materialId','restore-backup',
       CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(backup->'materials') bm WHERE bm->>'id'=r->>'materialId'
         AND lower(btrim(bm->>'code'))=lower(btrim(r->>'code'))) THEN NULL ELSE now() END
     FROM jsonb_array_elements(backup->'codeRegistry') r CROSS JOIN LATERAL inventory_private.code_parts(r->>'code') p
     ON CONFLICT DO NOTHING;
   END IF;
 ELSE
   -- QA-20261109 TX-03: 'correction' is a distinct mode so that a server WITHOUT correction support
   -- (e.g. SQL rolled back to #8, which accepts only mutation/audit) rejects the whole request atomically
   -- instead of committing it with an incomplete audit receipt.
   IF mode NOT IN ('mutation','audit','correction') OR jsonb_typeof(ops) IS DISTINCT FROM 'array' OR jsonb_array_length(ops)>450 OR jsonb_array_length(ops)=0
   THEN RAISE EXCEPTION 'INVENTORY_OPERATIONS_INVALID' USING ERRCODE='22023'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) x GROUP BY x->>'collection',x->>'docId' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'INVENTORY_DUPLICATE_OPERATION' USING ERRCODE='22023'; END IF;
 -- R8-R1 (RT-R8-02): materials whose STORED projection already disagrees with the ledger before this request.
 IF mode IN ('mutation','correction') THEN
   SELECT coalesce(array_agg(m.id),'{}') INTO pre_drift FROM public.materials m
   WHERE (EXISTS(SELECT 1 FROM jsonb_array_elements(ops) x WHERE x->>'collection'='settings')
       OR m.id IN (SELECT x->>'docId' FROM jsonb_array_elements(ops) x WHERE x->>'collection'='materials'
         UNION SELECT x->'value'->>'itemId' FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions'
         UNION SELECT x->'expected'->'data'->>'itemId' FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions'
         UNION SELECT t.data->>'itemId' FROM public.transactions t WHERE t.id IN (SELECT x->>'docId' FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions')))
     AND inventory_private.projection_status(m.data,inventory_private.material_projection(m.id))='drift';
 END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(ops) LOOP
   col:=op->>'collection';doc:=op->>'docId';kind:=op->>'kind';val:=op->'value';old:=NULL;business_equal:=false;
   IF col NOT IN ('settings','materials','transactions','generator_logs','users','audit_logs') OR nullif(btrim(doc),'') IS NULL OR length(doc)>200 OR kind NOT IN ('set','delete')
   THEN RAISE EXCEPTION 'INVENTORY_OPERATION_INVALID' USING ERRCODE='22023'; END IF;
   IF mode='audit' THEN
     IF col<>'audit_logs' OR kind<>'set' OR jsonb_array_length(ops)<>1 THEN RAISE EXCEPTION 'INVENTORY_AUDIT_MODE_INVALID' USING ERRCODE='22023'; END IF;
     -- R8-R1 (R2-R8-05): application events are server-controlled. A non-administrator may only report a known event
     -- type that matches its own capabilities (a read-only user: sign-in/out only), with a known item type, bounded
     -- text and a per-actor rate limit. Every receipt is attributed to the authenticated actor by the server.
     is_admin:=actor.permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb;
     IF jsonb_typeof(val) IS DISTINCT FROM 'object' OR nullif(btrim(val->>'action'),'') IS NULL
        OR coalesce(val->>'itemType','عام') NOT IN ('مادة','مبيد','معاملة','إعدادات','حركة','مولد','عام')
        OR length(coalesce(val->>'details',''))>8000
        OR (NOT is_admin AND NOT (val->>'action' IN ('تسجيل الدخول','تسجيل الخروج','طلب إعادة تعيين كلمة المرور')
          OR (actor.permissions ?| ARRAY['materials_create','materials_edit','materials_delete','transactions_create','transactions_delete','settings_edit','generator_log','users_manage']
              AND val->>'action' IN ('إضافة مادة جديدة','تعديل مادة','حذف مادة','إضافة حركة مخزنية','تعديل حركة مخزنية','إضافة حركات مخزنية',
                'حذف حركات مخزنية','تصحيح حركة مخزنية (إلغاء وبديل)','تحويل مخزني','تحديث سجلات المولد','تحديث الإعدادات','إدارة الحسابات والصلاحيات'))))
     THEN RAISE EXCEPTION 'INVENTORY_AUDIT_EVENT_DENIED' USING ERRCODE='42501'; END IF;
     IF NOT is_admin AND (SELECT count(*) FROM public.audit_logs a WHERE a.data->>'actorUserId'=actor.id AND a.data->>'result'='reported'
         AND a.updated_at>now()-interval '5 minutes')>=60
     THEN RAISE EXCEPTION 'INVENTORY_AUDIT_RATE_LIMITED' USING ERRCODE='54000'; END IF;
     CONTINUE;
   END IF;
   IF col='audit_logs' THEN RAISE EXCEPTION 'INVENTORY_AUDIT_IMMUTABLE' USING ERRCODE='42501'; END IF;
   EXECUTE format('SELECT data FROM public.%I WHERE id=$1 FOR UPDATE',col) INTO old USING doc;
   IF mode<>'restore' AND (NOT op ? 'expected' OR coalesce(op->'expected'->>'kind','') NOT IN ('present','missing') OR (op->'expected'->>'kind'='present' AND NOT op->'expected' ? 'data')) THEN RAISE EXCEPTION 'INVENTORY_BASELINE_REQUIRED' USING ERRCODE='40001'; END IF;
   IF mode<>'restore' AND op ? 'expected' THEN
     -- R8-DATA-01: only SERVER-OWNED material fields are ignored by the expected-document check; business fields stay exact.
     IF (op->'expected'->>'kind'='missing' AND old IS NOT NULL)
        OR (op->'expected'->>'kind'='present' AND (old IS NULL OR (op->'expected' ? 'data' AND
          CASE WHEN col='materials' THEN (op->'expected'->'data')-owned IS DISTINCT FROM old-owned ELSE op->'expected'->'data' IS DISTINCT FROM old END)))
     THEN RAISE EXCEPTION 'INVENTORY_CONFLICT' USING ERRCODE='40001'; END IF;
   END IF;
   IF kind='set' AND (jsonb_typeof(val) IS DISTINCT FROM 'object' OR val->>'id' IS DISTINCT FROM doc)
   THEN RAISE EXCEPTION 'INVENTORY_DOCUMENT_INVALID' USING ERRCODE='22023'; END IF;
   IF col='materials' AND mode<>'restore' THEN
     -- R8-ARC-01: archived items accept no new ledger effect and cannot be deleted or re-coded/re-homed.
     IF old IS NOT NULL AND old->>'lifecycleStatus'='archived' AND (kind='delete'
        OR (val-owned)->'code' IS DISTINCT FROM old->'code' OR (val-owned)->'category' IS DISTINCT FROM old->'category'
        OR (val-owned)->'initialStock' IS DISTINCT FROM old->'initialStock' OR (val-owned)->'primaryStorehouseId' IS DISTINCT FROM old->'primaryStorehouseId')
     THEN RAISE EXCEPTION 'INVENTORY_MATERIAL_ARCHIVED:%',doc USING ERRCODE='23514'; END IF;
     -- Server-owned fields (projection + lifecycle) always come from the stored row; a legacy whole-document write cannot clear them.
     IF kind='set' THEN
       val:=(val-owned)||coalesce((SELECT jsonb_object_agg(k,old->k) FROM unnest(owned) k WHERE old ? k),'{}'::jsonb);
       business_equal:=old IS NOT NULL AND (val-owned-'updatedAt')=(old-owned-'updatedAt')
         AND actor.permissions ?| ARRAY['materials_edit','materials_create','transactions_create','transactions_delete'];
     END IF;
     touched:=touched||doc;
   END IF;
   IF business_equal THEN CONTINUE; END IF; -- cache-only refresh: no write, no materials_edit needed; projection is recomputed below.
   IF col='materials' THEN direct:=direct||doc; END IF;
   IF mode<>'restore' THEN
     needed:=CASE col WHEN 'transactions' THEN CASE WHEN kind='delete' THEN 'transactions_delete' ELSE 'transactions_create' END
       WHEN 'generator_logs' THEN 'generator_log' WHEN 'users' THEN 'users_manage'
       WHEN 'settings' THEN 'settings_edit'
       WHEN 'materials' THEN CASE WHEN kind='delete' THEN 'materials_delete' WHEN old IS NULL THEN 'materials_create' ELSE 'materials_edit' END END;
     IF NOT actor.permissions ? needed THEN
       IF col='settings' AND kind='set' AND old IS NOT NULL AND actor.permissions ? 'transactions_create'
          AND val-'transactionCounters'-'updatedAt' = old-'transactionCounters'-'updatedAt'
          AND EXISTS(SELECT 1 FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions')
          AND jsonb_typeof(val->'transactionCounters')='object'
          AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(coalesce(old->'transactionCounters','{}')) k WHERE NOT val->'transactionCounters' ? k)
          AND NOT EXISTS(SELECT 1 FROM jsonb_each(val->'transactionCounters') c
            WHERE c.key NOT IN ('inbound','outbound','consumed','transfer','adjustment','opening')
              OR jsonb_typeof(c.value) IS DISTINCT FROM 'number'
              OR (c.value::text)::numeric <> trunc((c.value::text)::numeric)
              OR (c.value::text)::numeric < coalesce((old->'transactionCounters'->>c.key)::numeric,0)
              OR (c.value::text)::numeric > coalesce((old->'transactionCounters'->>c.key)::numeric,0)
                + (SELECT count(*) FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions' AND x->>'kind'='set'
                    AND x->'expected'->>'kind'='missing' AND x->'value'->>'transactionType'=CASE c.key WHEN 'inbound' THEN 'وارد' WHEN 'outbound' THEN 'صادر' WHEN 'consumed' THEN 'مستهلك' WHEN 'transfer' THEN 'تحويل' WHEN 'adjustment' THEN 'تسوية' ELSE 'افتتاحي' END)
                + (SELECT count(*) FROM public.transactions t WHERE t.data->>'transactionType'=CASE c.key WHEN 'inbound' THEN 'وارد' WHEN 'outbound' THEN 'صادر' WHEN 'consumed' THEN 'مستهلك' WHEN 'transfer' THEN 'تحويل' WHEN 'adjustment' THEN 'تسوية' ELSE 'افتتاحي' END
                    AND split_part(t.data->>'transactionNumber','-',2) ~ '^[0-9]+$'
                    AND (split_part(t.data->>'transactionNumber','-',2))::numeric > coalesce((old->'transactionCounters'->>c.key)::numeric,0))) THEN NULL;
       ELSIF col='materials' AND kind='set' AND old IS NOT NULL AND actor.permissions ? 'transactions_delete'
          AND val-'initialStock'-'updatedAt' = old-'initialStock'-'updatedAt'
          AND val->'initialStock'='0'::jsonb AND EXISTS(SELECT 1 FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions' AND x->>'kind'='delete' AND x->'expected'->'data'->>'itemId'=doc AND (x->'expected'->'data'->>'transactionType'='افتتاحي' OR x->>'docId' LIKE 'tr-init%')) THEN NULL;
       ELSE RAISE EXCEPTION 'INVENTORY_PERMISSION_DENIED:%',needed USING ERRCODE='42501'; END IF;
     END IF;
     IF col='settings' AND (doc<>'app_config' OR kind='delete') THEN RAISE EXCEPTION 'INVENTORY_SETTINGS_DELETE_DENIED' USING ERRCODE='42501'; END IF;
     IF col='transactions' AND kind='set' AND old IS NOT NULL AND
        (SELECT jsonb_agg(old->k ORDER BY k) FROM unnest(ARRAY['itemId','transactionType','transferType','quantity','date','storehouseId','transactionNumber','operationId','pairedTransactionId']) k)
        IS DISTINCT FROM (SELECT jsonb_agg(val->k ORDER BY k) FROM unnest(ARRAY['itemId','transactionType','transferType','quantity','date','storehouseId','transactionNumber','operationId','pairedTransactionId']) k)
     THEN RAISE EXCEPTION 'INVENTORY_LEDGER_IDENTITY_IMMUTABLE' USING ERRCODE='23514'; END IF;
     IF col IN ('materials','transactions') AND kind='set' AND (old IS NULL OR (col='materials' AND val->>'primaryStorehouseId' IS DISTINCT FROM old->>'primaryStorehouseId')) THEN
       SELECT data INTO cfg FROM public.settings WHERE id='app_config';
       IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'storehouseEntities') w WHERE w->>'id'=CASE col WHEN 'materials' THEN val->>'primaryStorehouseId' ELSE val->>'storehouseId' END AND w->'active'='true'::jsonb)
       THEN RAISE EXCEPTION 'INVENTORY_WAREHOUSE_INACTIVE' USING ERRCODE='23514'; END IF;
     END IF;
     IF col='materials' AND kind='set' AND old IS NOT NULL AND (val->'initialStock' IS DISTINCT FROM old->'initialStock' OR (val->>'primaryStorehouseId' IS DISTINCT FROM old->>'primaryStorehouseId' AND coalesce((old->>'initialStock')::numeric,0)<>0))
        AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ops) x WHERE x->>'collection'='transactions' AND (x->'value'->>'itemId'=doc OR x->'expected'->'data'->>'itemId'=doc))
     THEN RAISE EXCEPTION 'INVENTORY_OPENING_LEDGER_REQUIRED' USING ERRCODE='23514'; END IF;
     -- R8-CODE-01: create, code change and category change must satisfy the category policy (checked after all ops).
     IF col='materials' AND kind='set' AND (old IS NULL OR val->>'code' IS DISTINCT FROM old->>'code' OR val->>'category' IS DISTINCT FROM old->>'category')
     THEN strict_codes:=strict_codes||doc; END IF;
     IF col='transactions' AND (old IS NULL OR kind='delete') THEN
       ledger_items:=ledger_items||coalesce(val->>'itemId',old->>'itemId');
     END IF;
   END IF;
   IF col='transactions' THEN touched:=touched||coalesce(val->>'itemId',old->>'itemId'); IF old IS NOT NULL THEN touched:=touched||(old->>'itemId'); END IF;
     direct:=direct||coalesce(val->>'itemId',old->>'itemId'); IF old IS NOT NULL THEN direct:=direct||(old->>'itemId'); END IF; END IF;
   IF col='settings' THEN all_materials:=true; END IF;
   IF col='materials' AND kind='set' AND EXISTS(SELECT 1 FROM public.materials m WHERE m.id<>doc AND lower(btrim(m.data->>'code'))=lower(btrim(val->>'code')))
   THEN RAISE EXCEPTION 'INVENTORY_CODE_RESERVED:%',val->>'code' USING ERRCODE='23505'; END IF;
   IF col='users' THEN
     IF kind='set' AND (val->>'authUid' IS DISTINCT FROM doc
         OR nullif(btrim(val->>'fullName'),'') IS NULL OR nullif(btrim(val->>'role'),'') IS NULL
         OR jsonb_typeof(val->'active') IS DISTINCT FROM 'boolean'
         OR jsonb_typeof(val->'permissions') IS DISTINCT FROM 'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(val->'permissions') p WHERE jsonb_typeof(p) IS DISTINCT FROM 'string'))
     THEN RAISE EXCEPTION 'INVENTORY_PROFILE_INVALID' USING ERRCODE='23514'; END IF;
     IF val ?| ARRAY['password','passwordHash','access_token','refresh_token','service_role'] THEN RAISE EXCEPTION 'INVENTORY_PROFILE_SECRET_REJECTED' USING ERRCODE='22023'; END IF;
     IF kind='delete' THEN RAISE EXCEPTION 'INVENTORY_USER_DELETE_DENIED' USING ERRCODE='42501'; END IF;
     IF NOT EXISTS(SELECT 1 FROM auth.users a WHERE a.id::text=coalesce(val->>'authUid',doc) AND lower(a.email)=lower(val->>'username'))
     THEN RAISE EXCEPTION 'INVENTORY_AUTH_IDENTITY_MISSING' USING ERRCODE='23514'; END IF;
     INSERT INTO public.users(id,auth_uid,username,full_name,role,permissions,active,created_at,data,updated_at)
     VALUES(doc,coalesce(val->>'authUid',doc),val->>'username',val->>'fullName',val->>'role',val->'permissions',coalesce((val->>'active')::boolean,true),coalesce(val->>'createdAt',stamp),val,now())
     ON CONFLICT(id) DO UPDATE SET auth_uid=excluded.auth_uid,username=excluded.username,full_name=excluded.full_name,role=excluded.role,permissions=excluded.permissions,active=excluded.active,data=excluded.data,updated_at=now();
   ELSIF kind='delete' THEN
     IF old IS NULL THEN RAISE EXCEPTION 'INVENTORY_DELETE_MISSING' USING ERRCODE='40001'; END IF;
     EXECUTE format('DELETE FROM public.%I WHERE id=$1',col) USING doc;
     IF col='materials' THEN UPDATE inventory_private.material_code_registry SET deleted_at=now() WHERE material_id=doc AND deleted_at IS NULL; END IF;
   ELSE
     EXECUTE format('INSERT INTO public.%I(id,data,updated_at) VALUES($1,$2,now()) ON CONFLICT(id) DO UPDATE SET data=excluded.data,updated_at=now()',col) USING doc,val;
   END IF;
   affected:=affected||jsonb_build_array(col||'/'||doc);
   -- QA-20261108 TX-03 (isolated only): keep the ORIGINAL values of a cancelled ledger entry in the receipt and link a correction to it.
   IF mode<>'restore' AND col='transactions' AND kind='delete' AND old IS NOT NULL THEN
     removed:=removed||jsonb_build_array(jsonb_build_object('id',doc,'transactionNumber',old->>'transactionNumber','transactionType',old->>'transactionType',
       'quantity',old->'quantity','date',old->>'date','itemId',old->>'itemId','itemCode',old->>'itemCode','storehouseId',old->>'storehouseId','unit',old->>'unit'));
   END IF;
   -- QA-20261109 TX-03: a NEW replacement row carrying correctionOf is only accepted in correction mode.
   IF col='transactions' AND kind='set' AND old IS NULL AND mode='mutation' AND jsonb_typeof(val->'correctionOf')='object'
   THEN RAISE EXCEPTION 'INVENTORY_CORRECTION_MODE_REQUIRED' USING ERRCODE='22023'; END IF;
   IF mode='correction' AND col='transactions' AND kind='set' AND old IS NULL AND jsonb_typeof(val->'correctionOf')='object' THEN
     corr:=corr||jsonb_build_array(jsonb_build_object('originalId',val->'correctionOf'->>'id','originalNumber',val->'correctionOf'->>'transactionNumber',
       'originalQuantity',val->'correctionOf'->'quantity','replacementId',doc,'replacementNumber',val->>'transactionNumber','replacementQuantity',val->'quantity',
       'reason',left(coalesce(val->'correctionOf'->>'reason',''),500)));
   END IF;
 END LOOP;
 IF mode='correction' AND jsonb_array_length(corr)=0 THEN RAISE EXCEPTION 'INVENTORY_CORRECTION_LINK_INVALID' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(corr) c WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(removed) r
     WHERE r->>'id'=c->>'originalId' AND r->>'transactionNumber' IS NOT DISTINCT FROM c->>'originalNumber'
       AND (r->>'quantity')::numeric IS NOT DISTINCT FROM (c->>'originalQuantity')::numeric))
 THEN RAISE EXCEPTION 'INVENTORY_CORRECTION_LINK_INVALID' USING ERRCODE='23514'; END IF;
 IF mode<>'audit' THEN
   -- R8-ARC-01: no new ledger effect (create/delete/correction/either transfer leg/opening/import) on an archived item.
   -- Lifecycle is server-owned and unchanged by this mode, so the stored state is both the old and the final state.
   IF EXISTS(SELECT 1 FROM public.materials m WHERE m.id=ANY(ledger_items) AND m.data->>'lifecycleStatus'='archived')
   THEN RAISE EXCEPTION 'INVENTORY_MATERIAL_ARCHIVED' USING ERRCODE='23514'; END IF;
   -- R8-R1 (RT-R8-11): deleting the last opening row must also clear initialStock in the same request; otherwise the
   -- initialStock fallback would silently re-create the cancelled opening balance.
   IF mode IN ('mutation','correction') AND EXISTS(SELECT 1 FROM jsonb_array_elements(removed) r JOIN public.materials m ON m.id=r->>'itemId'
       WHERE (r->>'transactionType'='افتتاحي' OR r->>'id' LIKE 'tr-init%') AND coalesce((m.data->>'initialStock')::numeric,0)<>0
         AND NOT EXISTS(SELECT 1 FROM public.transactions t WHERE t.data->>'itemId'=m.id AND (t.data->>'transactionType'='افتتاحي' OR t.id LIKE 'tr-init%')))
   THEN RAISE EXCEPTION 'INVENTORY_OPENING_LEDGER_REQUIRED' USING ERRCODE='23514'; END IF;
   SELECT data INTO cfg FROM public.settings WHERE id='app_config';
   -- New codes are reserved in ascending central order, so an import batch of consecutive codes is accepted in one request.
   FOR mid IN SELECT u.id FROM unnest(strict_codes) WITH ORDINALITY u(id,o) JOIN public.materials m ON m.id=u.id
       CROSS JOIN LATERAL inventory_private.code_parts(m.data->>'code') p ORDER BY p->>'prefix',(p->>'number')::numeric,u.o LOOP
     SELECT data INTO val FROM public.materials WHERE id=mid;
     IF val IS NOT NULL THEN PERFORM inventory_private.reserve_material_code(mid,val,cfg,true,mode); END IF;
   END LOOP;
   FOREACH mid IN ARRAY restore_codes LOOP
     SELECT data INTO val FROM public.materials WHERE id=mid;
     IF val IS NOT NULL THEN PERFORM inventory_private.reserve_material_code(mid,val,cfg,false,'restore'); END IF;
   END LOOP;
   IF mode='restore' THEN
     UPDATE inventory_private.material_code_registry r SET deleted_at=now()
     WHERE r.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.materials m WHERE m.id=r.material_id AND lower(btrim(m.data->>'code'))=r.code_key);
   END IF;
   -- R8-DATA-01: recompute the ledger projection of every affected material inside this same locked transaction.
   IF all_materials THEN SELECT coalesce(array_agg(id ORDER BY id),'{}') INTO proj_ids FROM public.materials;
   ELSE SELECT coalesce(array_agg(DISTINCT x ORDER BY x),'{}') INTO proj_ids FROM unnest(touched) x WHERE x IS NOT NULL AND EXISTS(SELECT 1 FROM public.materials m WHERE m.id=x); END IF;
   FOREACH mid IN ARRAY proj_ids LOOP
     SELECT data INTO val FROM public.materials WHERE id=mid;
     IF mid=ANY(pre_drift) THEN
       -- A ledger or business change to a drifted material is refused (nothing written); a settings-wide or cache-only
       -- refresh keeps the drifted stored value untouched and reports it. Only mode 'reconcile' corrects it.
       IF mid=ANY(direct) THEN RAISE EXCEPTION 'INVENTORY_RECONCILE_REQUIRED:%',coalesce(val->>'code',mid) USING ERRCODE='23514'; END IF;
       held:=held||jsonb_build_array(mid); CONTINUE;
     END IF;
     before_d:=inventory_private.stored_projection(val); after_d:=inventory_private.material_projection(mid);
     IF before_d IS DISTINCT FROM after_d THEN
       UPDATE public.materials SET data=(data-derived)||after_d,updated_at=now() WHERE id=mid;
       IF jsonb_array_length(proj_changes)<100 THEN
         proj_changes:=proj_changes||jsonb_build_array(jsonb_build_object('id',mid,'before',before_d,'after',after_d));
       END IF;
     END IF;
   END LOOP;
   PERFORM inventory_private.validate_inventory();
   IF NOT EXISTS(SELECT 1 FROM public.users WHERE active AND permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb)
   THEN RAISE EXCEPTION 'INVENTORY_LAST_ADMIN_REQUIRED' USING ERRCODE='23514'; END IF;
   -- Always present (possibly []) outside restore so a client can tell a server-projected ACK from an older server.
   IF mode<>'restore' THEN extra:=extra||jsonb_build_object('projectedMaterialIds',coalesce((SELECT jsonb_agg(x ORDER BY x) FROM unnest(proj_ids) x
     WHERE NOT held ? x),'[]'::jsonb)); END IF;
   IF jsonb_array_length(proj_changes)>0 THEN extra:=extra||jsonb_build_object('projectionUpdates',proj_changes); END IF;
   IF jsonb_array_length(lc_preserved)>0 THEN extra:=extra||jsonb_build_object('lifecyclePreserved',lc_preserved); END IF;
   IF jsonb_array_length(held)>0 THEN extra:=extra||jsonb_build_object('projectionDriftHeld',held); END IF;
 END IF;
 receipt:=jsonb_build_object('id',p_mutation_id,'timestamp',stamp,'user',actor.full_name,'actorUserId',actor.id,'actorDisplayName',actor.full_name,
   'action',CASE WHEN mode='restore' THEN 'استعادة بيانات التطبيق' WHEN mode='audit' THEN left(ops->0->'value'->>'action',200) WHEN jsonb_array_length(corr)>0 THEN 'تصحيح حركة مخزنية (إلغاء وبديل)' ELSE 'اعتماد عملية مخزنية' END,
   'details',CASE mode WHEN 'audit' THEN left(ops->0->'value'->>'details',8000) ELSE 'تم اعتماد العملية وجميع سجلاتها معًا.' END,
   'itemType',CASE mode WHEN 'audit' THEN coalesce(ops->0->'value'->>'itemType','عام') WHEN 'restore' THEN 'إعدادات' ELSE 'حركة' END,
   'operationType',CASE WHEN mode='restore' THEN 'backup' ELSE 'system' END,'affectedEntities',affected,
   'result',CASE WHEN mode='audit' THEN 'reported' ELSE 'committed' END,'mutationDigest',digest,'mutationLabel',left(p_payload->>'label',160))
   ||CASE WHEN jsonb_array_length(removed)>0 THEN jsonb_build_object('removedTransactions',removed) ELSE '{}'::jsonb END
   ||CASE WHEN jsonb_array_length(corr)>0 THEN jsonb_build_object('corrections',corr) ELSE '{}'::jsonb END
   ||extra;
 INSERT INTO public.audit_logs(id,data,updated_at) VALUES(p_mutation_id,receipt,now());
 RETURN jsonb_build_object('audit',receipt,'replayed',false,'results',results,'materials',inventory_private.material_rows(receipt->'projectedMaterialIds'));
END;
$$;

CREATE OR REPLACE FUNCTION public.inventory_commit(p_mutation_id text,p_payload jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT inventory_private.commit_inventory(p_mutation_id,p_payload); $$;

CREATE OR REPLACE FUNCTION inventory_private.restore_preview(p_backup jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor public.users%ROWTYPE; diffs jsonb:='{}'; col text; key text; old_count int; new_count int; added int; removed int; changed int;
BEGIN
 SELECT * INTO actor FROM public.users WHERE auth_uid=auth.uid()::text AND active;
 IF actor.id IS NULL OR NOT actor.permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb
 THEN RAISE EXCEPTION 'INVENTORY_RESTORE_DENIED' USING ERRCODE='42501'; END IF;
 IF octet_length(p_backup::text)>4000000 OR jsonb_typeof(p_backup->'settings') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVENTORY_BACKUP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(824671520);
 FOR col IN SELECT unnest(ARRAY['materials','transactions','generator_logs','users']) LOOP
   key:=CASE WHEN col='generator_logs' THEN 'generatorLogs' ELSE col END;
   IF jsonb_typeof(p_backup->key) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVENTORY_BACKUP_INVALID' USING ERRCODE='22023'; END IF;
   EXECUTE format('SELECT count(*),count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements($1) b WHERE b->>''id''=t.id)),count(*) FILTER(WHERE EXISTS(SELECT 1 FROM jsonb_array_elements($1) b WHERE b->>''id''=t.id AND b IS DISTINCT FROM t.data)) FROM public.%I t',col)
     INTO old_count,removed,changed USING p_backup->key;
   EXECUTE format('SELECT count(*) FROM jsonb_array_elements($1) b WHERE NOT EXISTS(SELECT 1 FROM public.%I t WHERE t.id=b->>''id'')',col) INTO added USING p_backup->key;
   diffs:=diffs||jsonb_build_object(col,jsonb_build_object('current',old_count,'backup',jsonb_array_length(p_backup->key),'added',added,'removed',removed,'changed',changed));
 END LOOP;
 diffs:=diffs||jsonb_build_object('settings',jsonb_build_object('current',(SELECT count(*) FROM public.settings WHERE id='app_config'),'backup',1,'added',0,'removed',0,'changed',CASE WHEN (SELECT data-'id' FROM public.settings WHERE id='app_config') IS DISTINCT FROM ((p_backup->'settings')-'id') THEN 1 ELSE 0 END));
 RETURN jsonb_build_object('expectedState',inventory_private.state_hash(),'diffs',diffs,'auditHistory','preserved','authIdentities','preserved');
END;
$$;
CREATE OR REPLACE FUNCTION public.inventory_restore_preview(p_backup jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT inventory_private.restore_preview(p_backup); $$;


-- R8-DATA-01: read-only drift check over ALL materials (no write, no recurring routine).
CREATE OR REPLACE FUNCTION inventory_private.projection_drift() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor public.users%ROWTYPE; rows jsonb;
BEGIN
 SELECT * INTO actor FROM public.users WHERE auth_uid=auth.uid()::text AND active;
 IF actor.id IS NULL OR NOT (actor.permissions @> '["materials_view","transactions_view"]'::jsonb)
 THEN RAISE EXCEPTION 'INVENTORY_DRIFT_DENIED' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]'::jsonb) INTO rows FROM (
   SELECT jsonb_build_object('id',m.id,'code',m.data->>'code','lifecycleStatus',coalesce(m.data->>'lifecycleStatus','active'),
     'stored',inventory_private.stored_projection(m.data),'computed',p.p,
     'status',inventory_private.projection_status(m.data,p.p),
     'ledgerRows',(SELECT count(*) FROM public.transactions t WHERE t.data->>'itemId'=m.id),'ledgerHash',inventory_private.material_ledger_hash(m.id)) x
   FROM public.materials m CROSS JOIN LATERAL inventory_private.material_projection(m.id) p(p)) q;
 RETURN jsonb_build_object('materials',jsonb_array_length(rows),
   'drift',(SELECT count(*) FROM jsonb_array_elements(rows) r WHERE r->>'status'='drift'),'rows',rows);
END;
$$;
CREATE OR REPLACE FUNCTION public.inventory_projection_drift() RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT inventory_private.projection_drift(); $$;

-- R8-CODE-01: central next-code read based on ALL materials (active, archived) plus the permanent registry.
-- The code becomes reserved only when commit_inventory accepts the create; a concurrent loser gets
-- INVENTORY_CODE_RESERVED (atomic, nothing written) and simply asks for the next code again.
CREATE OR REPLACE FUNCTION inventory_private.next_material_code(p_category text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor public.users%ROWTYPE; cfg jsonb; c jsonb; n numeric;
BEGIN
 SELECT * INTO actor FROM public.users WHERE auth_uid=auth.uid()::text AND active;
 IF actor.id IS NULL OR NOT (actor.permissions ?| ARRAY['materials_create','materials_edit']) THEN RAISE EXCEPTION 'INVENTORY_CODE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT data INTO cfg FROM public.settings WHERE id='app_config';
 SELECT x INTO c FROM jsonb_array_elements(cfg->'categories') x WHERE x->>'name'=p_category;
 IF c IS NULL OR coalesce(c->>'prefix','') !~ '^[A-Z]{2,6}$' THEN RAISE EXCEPTION 'INVENTORY_CATEGORY_UNKNOWN' USING ERRCODE='22023'; END IF;
 SELECT greatest((c->>'startRange')::numeric-1,
   coalesce((SELECT max(r.number) FROM inventory_private.material_code_registry r WHERE r.prefix=c->>'prefix'),0),
   coalesce((SELECT max((inventory_private.code_parts(m.data->>'code')->>'number')::numeric) FROM public.materials m
     WHERE inventory_private.code_parts(m.data->>'code')->>'prefix'=c->>'prefix'),0))+1 INTO n;
 IF n>(c->>'endRange')::numeric THEN RAISE EXCEPTION 'INVENTORY_CODE_RANGE_EXHAUSTED:%',c->>'prefix' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('code',(c->>'prefix')||'-'||n::text,'prefix',c->>'prefix','number',n,'category',p_category,'provisional',true);
END;
$$;
CREATE OR REPLACE FUNCTION public.inventory_next_material_code(p_category text) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT inventory_private.next_material_code(p_category); $$;

-- R8-R1 (RT-R8-04): read the permanent code registry for a full backup (administrators only; read-only).
CREATE OR REPLACE FUNCTION inventory_private.code_registry_export() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor public.users%ROWTYPE;
BEGIN
 SELECT * INTO actor FROM public.users WHERE auth_uid=auth.uid()::text AND active;
 IF actor.id IS NULL OR NOT actor.permissions @> '["users_manage","settings_edit","system_reset"]'::jsonb
 THEN RAISE EXCEPTION 'INVENTORY_CODE_REGISTRY_DENIED' USING ERRCODE='42501'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('code',r.code,'materialId',r.material_id,'deleted',r.deleted_at IS NOT NULL) ORDER BY r.code_key)
   FROM inventory_private.material_code_registry r),'[]'::jsonb);
END;
$$;
CREATE OR REPLACE FUNCTION public.inventory_code_registry() RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT inventory_private.code_registry_export(); $$;

REVOKE ALL ON FUNCTION inventory_private.state_hash(),inventory_private.validate_inventory(),inventory_private.commit_inventory(text,jsonb),inventory_private.restore_preview(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION inventory_private.derived_material_keys(),inventory_private.lifecycle_material_keys(),inventory_private.server_owned_material_keys(),
  inventory_private.code_parts(text),inventory_private.material_projection(text),inventory_private.material_ledger_hash(text),inventory_private.stored_projection(jsonb),
  inventory_private.material_rows(jsonb),inventory_private.validate_category_config(jsonb),inventory_private.code_matches_category(text,text,jsonb),
  inventory_private.reserve_material_code(text,jsonb,jsonb,boolean,text),inventory_private.projection_drift(),inventory_private.next_material_code(text),
  inventory_private.projection_status(jsonb,jsonb),inventory_private.code_registry_export() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION inventory_private.commit_inventory(text,jsonb),inventory_private.restore_preview(jsonb),inventory_private.projection_drift(),inventory_private.next_material_code(text),inventory_private.code_registry_export() TO authenticated;
REVOKE ALL ON FUNCTION public.inventory_commit(text,jsonb),public.inventory_restore_preview(jsonb),public.inventory_projection_drift(),public.inventory_next_material_code(text),public.inventory_code_registry() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.inventory_commit(text,jsonb),public.inventory_restore_preview(jsonb),public.inventory_projection_drift(),public.inventory_next_material_code(text),public.inventory_code_registry() TO authenticated;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.materials,public.transactions,public.generator_logs,public.settings,public.audit_logs,public.users FROM authenticated;
REVOKE TRUNCATE ON public.users FROM authenticated;
REVOKE ALL ON public.materials,public.transactions,public.generator_logs,public.settings,public.audit_logs,public.users FROM anon,PUBLIC;
-- Existing read RLS remains in force. Service role and Auth provisioning are unchanged.

-- Post-condition inside the same transaction: current data must satisfy the new invariants, otherwise everything rolls back.
DO $r8_post$ BEGIN PERFORM inventory_private.validate_inventory(); END $r8_post$;
COMMIT;
